const item = $input.first().json;
const msg = item.message || {};
const chat_id = String(msg.chat?.id || '');
const user_id = Number(msg.from?.id || 0);
const update_id = Number(item.update_id || 0);
const message_id = Number(msg.message_id || 0);
let text = msg.text || '';
let has_voice = false;
let voice_file_id = '';

if (msg.voice) { has_voice = true; voice_file_id = msg.voice.file_id; }
else if (msg.audio) { has_voice = true; voice_file_id = msg.audio.file_id; }

return [{ json: { chat_id, user_id, update_id, message_id, text, has_voice, voice_file_id } }];

